examples:
Syntax:
if (condition) {
  // block of code to be executed if
  // the condition is true
}

Example:
let age = 25;
if (age < 18) {
  greeting = "Good day";
}
let text = "Good morning";
if (age > 18) {
  greeting = "Good evening";
}

Examples:
if (age < 18) {
  if (text > 16) {
    text = "Good day";
  }
}

if (age >= 18) {
  if (text >= 18) {
    text = "Good evening";
  }
}

